#include "ksStateProgramTask.h"
#include <iostream>
#include <vector>
#include <utility>
#include <stdexcept>
using T=ks::StateProgramTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned kind=0;kind<3;++kind)for(unsigned value=0;value<65536;++value){T task(T::Kind(kind),value);unsigned reads=0,clocks=0,children=0;std::vector<std::pair<T::Write,unsigned>> writes;const unsigned bank=value>>8,program=value&255,storeClocks=value&3;auto read=[&](T::Read r)->unsigned{++reads;return r==T::Read::Bank?bank:program;};auto write=[&](T::Write w,uint8_t v){writes.emplace_back(w,v);};while(!task.complete()){if(task.awaitingMode()){++children;check(task.resumeMode(),"Mode child rejected");continue;}const auto c=task.nextClocks(storeClocks),before=reads;const auto stores=writes.size();check(!task.advanceBefore(c-1,read,write,storeClocks)&&reads==before&&writes.size()==stores,"Program early read/write");check(task.advanceBefore(c,read,write,storeClocks)==c,"Program admission differs");clocks+=c;}
 unsigned expectedClocks;if(kind==0){const unsigned b=uint8_t(bank-1);const unsigned expected=program+(b<=4?b*100:400+(b-4)*50);check(task.index()==expected&&reads==2&&writes.empty()&&!children,"Bank/program index differs");expectedClocks=132+unsigned(b>4)*9;}else if(kind==1){const unsigned divisor=value<450?100:50,bias=value<450?0:4,n=value<450?value:value-400;const unsigned expectedBank=uint8_t(uint8_t(n/divisor)+bias+1),expectedProgram=n%divisor;check(writes==std::vector<std::pair<T::Write,unsigned>>{{T::Write::Program,expectedProgram},{T::Write::Bank,expectedBank}}&&!reads&&children==1&&task.bank()==expectedBank&&task.program()==expectedProgram,"Index quotient/remainder/byte wrap differs");expectedClocks=91+2*storeClocks+unsigned(value>=450)*12;}else{check(task.slotAddress()==0x167ae +uint8_t(program*2)&&reads==1&&writes.empty()&&!children,"Part slot byte wrap differs");expectedClocks=44;}
 if(clocks!=expectedClocks){std::cerr<<"kind="<<kind<<" value="<<value<<" clocks="<<clocks<<" expected="<<expectedClocks<<'\n';throw std::runtime_error("Program clocks differ");}check(!task.resumeMode(),"Program restarted");++cases;}
 std::cout<<"PASS: "<<cases<<" complete program codecs/part slot jobs,allbank+program bytes/all65536indices,quotient/remainder wrap/split boundaries/typed mode request/exact clocks/deadlines\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
